mapper.select:
SELECT , c.CUSTOMER_NAME, r.DOCUMENT_NO
FROM TBL_AR_BAD_DEBT_WRITE_OFF w
LEFT JOIN TBL_AR_CUSTOMER c ON w.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
LEFT JOIN TBL_AR_RECEIVABLE r ON w.RECEIVABLE_ID = r.RECEIVABLE_ID AND r.IS_DELETED = 0
WHERE w.IS_DELETED = 0

    AND w.WRITE_OFF_NO LIKE '%' || #{param.writeOffNo} || '%'


    AND w.CUSTOMER_ID = #{param.customerId}


    AND c.CUSTOMER_NAME LIKE '%' || #{param.customerName} || '%'


    AND w.WRITE_OFF_STATUS = #{param.writeOffStatus}


    AND w.WRITE_OFF_DATE >= #{param.writeOffDateStart}


    AND w.WRITE_OFF_DATE <= #{param.writeOffDateEnd}


    AND w.TENANT_ID = #{param.tenantId}


    AND w.ORG_ID = #{param.orgId}

ORDER BY w.CREATE_TIME DESC

SELECT , c.CUSTOMER_NAME, r.DOCUMENT_NO FROM TBL_AR_BAD_DEBT_WRITE_OFF w LEFT JOIN TBL_AR_CUSTOMER c ON w.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 LEFT JOIN TBL_AR_RECEIVABLE r ON w.RECEIVABLE_ID = r.RECEIVABLE_ID AND r.IS_DELETED = 0 WHERE w.IS_DELETED = 0
AND w.TENANT_ID = #{param.tenantId}
ORDER BY w.CREATE_TIME DESC
